139	    @Test
140	    void concurrentResolveAndDeleteNeverOverwritesOrResurrects() throws Exception {
141	        setupLocationConflict("obs-x2", "x2");
142	
143	        List<Callable<String>> tasks = List.of(
144	                () -> {
145	                    try {
146	                        observationService.resolveConflict(
147	                                "obs-x2", resolveRequest("req-x2-r", "res-x2", 2));
148	                        return "resolve-ok";
149	                    } catch (ApiException e) {
150	                        return "resolve-" + e.status().value();
151	                    }
152	                },
153	                () -> {
154	                    try {
155	                        observationService.delete("obs-x2", new DeleteObservationRequest("req-x2-d", 2));
156	                        return "delete-ok";
157	                    } catch (ApiException e) {
158	                        return "delete-" + e.status().value();
159	                    }
160	                });
161	        List<String> results = runConcurrently(tasks);
162	
163	        ObservationResponse current = observationService.getCurrent("obs-x2");
164	        if (results.contains("resolve-ok")) {
165	            // 解决先生效：内容为站点C/v3，删除因版本不匹配失败
166	            assertThat(results).containsExactlyInAnyOrder("resolve-ok", "delete-409");
167	            assertThat(current.deleted()).isFalse();
