import java.util.Locale;

/**
 * 读数量纲：长度（LENGTH，规范单位 m）或温度（TEMPERATURE，规范单位 C）。
 * 每条观测创建时固定量纲，后续提交不得跨量纲；旧无单位读数量纲为 null，不自动推断。
