        return switch (value.trim().toUpperCase(Locale.ROOT)) {
            case "LENGTH" -> LENGTH;
            case "TEMPERATURE" -> TEMPERATURE;
            default -> null;
        };
    }

    /** 该量纲的规范单位符号：长度为 m，温度为 C。 */
    public String canonicalUnit() {
