/**
 * 一次带量纲读数输入：原值、原始单位与精确规范值。
 * 解析规则：dimension 与 unit 必须同时出现或同时缺省（缺省为旧无单位读数）；
 * 单位必须属于所给量纲且受支持，值最多三位小数；任何违反均 400。
 */
public record DimensionalReading(Dimension dimension, ReadingUnit unit, String value, String normalizedValue) {

    private static final Pattern VALUE_PATTERN = Pattern.compile("-?\\d+(\\.\\d{1,3})?");

    /** 解析请求中的量纲读数；两者均缺省时返回 null 表示旧无单位读数。 */
    public static DimensionalReading parse(String dimension, String unit, String value) {
        if (dimension == null && unit == null) return null;
        if (dimension == null || unit == null) throw badRequest("dimension and readingUnit must be provided together");
        Dimension dim = Dimension.fromValue(dimension);
        if (dim == null) throw badRequest("unsupported dimension: " + dimension);
        ReadingUnit u = ReadingUnit.fromSymbol(unit);
        if (u == null || u.dimension() != dim) throw badRequest("unsupported unit for dimension " + dim + ": " + unit);
        if (value == null || !VALUE_PATTERN.matcher(value).matches()) throw badRequest("reading must be a decimal string with at most 3 fraction digits");
        return new DimensionalReading(dim, u, value, u.normalize(new BigDecimal(value)).toPlainString());
    }
}
