package com.example.starter.observation;

import java.math.BigDecimal;
import java.util.regex.Pattern;

/**
 * 一次带量纲读数输入：原值、原始单位与精确规范值。
 *
 * <p>解析规则：dimension 与 readingUnit 必须同时出现或同时缺省（同时缺省表示旧无单位读数，返回 null）；
 * 单位必须受支持且属于所给量纲，值必须是最多三位小数的十进制字符串；任何违反均抛 400。
 * 规范值按单位精确换算（cm/100、K-273.15），不舍入，合并比较使用该精确值。
 *
 * @param dimension       读数量纲
 * @param unit            原始单位
 * @param value           原始读数（十进制原文，最多三位小数）
 * @param normalizedValue 精确规范读数（长度 m、温度 C，十进制原文，可能超过三位小数）
 */
public record DimensionalReading(Dimension dimension, ReadingUnit unit, String value, String normalizedValue) {

    private static final Pattern VALUE_PATTERN = Pattern.compile("-?\\d+(\\.\\d{1,3})?");

    /**
     * 解析请求中的量纲读数；dimension 与 readingUnit 均缺省时返回 null（旧无单位读数，不推断量纲）。
     */
    public static DimensionalReading parse(String dimension, String unit, String value) {
        if (dimension == null && unit == null) {
            return null;
        }
        if (dimension == null || unit == null) {
            throw ApiException.badRequest("dimension and readingUnit must be provided together");
        }
        Dimension parsedDimension = Dimension.fromValue(dimension);
        if (parsedDimension == null) {
            throw ApiException.badRequest("unsupported dimension: " + dimension);
        }
        ReadingUnit parsedUnit = ReadingUnit.fromSymbol(unit);
        if (parsedUnit == null || parsedUnit.dimension() != parsedDimension) {
            throw ApiException.badRequest(
                    "unsupported unit for dimension " + parsedDimension.name() + ": " + unit);
        }
        if (value == null || !VALUE_PATTERN.matcher(value).matches()) {
            throw ApiException.badRequest(
                    "reading must be a decimal string with at most 3 fraction digits");
        }
        return new DimensionalReading(parsedDimension, parsedUnit, value,
                parsedUnit.normalize(new BigDecimal(value)).toPlainString());
    }
}

package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;

/**
 * 源输入收件持久化：reading_receipt 只插不改，与业务变更同事务提交。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class ReadingReceiptRepository {

    private static final RowMapper<ReadingReceipt> RECEIPT_MAPPER = (rs, rowNum) -> new ReadingReceipt(
            rs.getString("request_id"),
            rs.getString("observation_id"),
            rs.getString("operation"),
            rs.getString("dimension"),
            rs.getString("original_reading"),
            rs.getString("original_unit"),
            rs.getString("normalized_reading"),
            rs.getString("operator"),
            rs.getTimestamp("received_at_utc").toInstant());

    private static final String SELECT_COLUMNS =
            "request_id, observation_id, operation, dimension, original_reading, original_unit, "
                    + "normalized_reading, operator, received_at_utc";

    private final JdbcTemplate jdbcTemplate;

    public ReadingReceiptRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 在写事务内插入一条收件记录；业务失败时随事务回滚，不留收件。
     */
    public void insert(ReadingReceipt receipt) {
        jdbcTemplate.update(
                "INSERT INTO reading_receipt (request_id, observation_id, operation, dimension, "
                        + "original_reading, original_unit, normalized_reading, operator, received_at_utc, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                receipt.requestId(),
                receipt.observationId(),
                receipt.operation(),
                receipt.dimension(),
                receipt.originalReading(),
                receipt.originalUnit(),
                receipt.normalizedReading(),
                receipt.operator(),
                Timestamp.from(receipt.receivedAtUtc()));
    }

    /**
     * 按观测记录查询全部收件记录，按收件先后排序。
     */
    public List<ReadingReceipt> findByObservationId(String observationId) {
        return jdbcTemplate.query(
                "SELECT " + SELECT_COLUMNS + " FROM reading_receipt WHERE observation_id = ? "
                        + "ORDER BY created_at ASC, request_id ASC",
                RECEIPT_MAPPER, observationId);
    }
}

