    assertThat(frozen).isEqualTo("2");
}

@Test
void resolveWithCrossDimensionCandidateIsRejected() throws Exception {
    create("req-c1", "obs-cd", "站点A", "1", "备注", "LENGTH", "m", null)
            .andExpect(status().isCreated());
