package com.example.starter.observation;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 带量纲读数并发边界测试：真实并发提交，验证等价规范值合并只推进一次版本、
 * 同键并发重放只占一键且不重复收件（真实 H2 内存库，MySQL 兼容模式）。
 */
@SpringBootTest
class DimensionalReadingConcurrencyTest {

    @Autowired
    private ObservationService observationService;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanDatabase() {
        jdbcTemplate.update("DELETE FROM reading_receipt");
        jdbcTemplate.update("DELETE FROM conflict_resolution");
        jdbcTemplate.update("DELETE FROM request_log");
        jdbcTemplate.update("DELETE FROM observation_version");
        jdbcTemplate.update("DELETE FROM observation_current");
    }

    private <T> List<T> runConcurrently(List<Callable<T>> tasks) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(tasks.size());
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch start = new CountDownLatch(1);
        List<Callable<T>> synchronizedTasks = tasks.stream()
                .<Callable<T>>map(task -> () -> {
                    ready.countDown();
                    start.await(10, TimeUnit.SECONDS);
                    return task.call();
                })
                .toList();
        try {
            List<Future<T>> futures = synchronizedTasks.stream().map(executor::submit).toList();
            if (!ready.await(10, TimeUnit.SECONDS)) {
                throw new IllegalStateException("workers not ready in time");
            }
            start.countDown();
            List<T> results = new ArrayList<>();
            for (Future<T> future : futures) {
                results.add(future.get(30, TimeUnit.SECONDS));
            }
            return results;
        } finally {
            executor.shutdownNow();
        }
    }

    @Test
    void concurrentEquivalentMergesBumpVersionOnlyOnce() throws Exception {
        observationService.create(new CreateObservationRequest(
                "req-e0", "obs-eq", "站点A", "1", "基线", "LENGTH", "m", null));

        // 两个离线端都基于 v1：200cm 与 2m 规范值等价（均为 2m），并发提交
        List<Callable<ObservationService.WriteOutcome>> tasks = List.of(
                () -> observationService.merge("obs-eq", new MergeObservationRequest(
                        "req-e1", 1, "站点A", "200", "基线", "LENGTH", "cm", null)),
                () -> observationService.merge("obs-eq", new MergeObservationRequest(
                        "req-e2", 1, "站点A", "2", "基线", "LENGTH", "m", null)));
        List<ObservationService.WriteOutcome> outcomes = runConcurrently(tasks);

        // 两个请求都成功：先到者推进到 v2，后到者基于最新版本判定为等价，不再加版本
        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
        ObservationResponse current = observationService.getCurrent("obs-eq");
        assertThat(current.version()).isEqualTo(2);
        assertThat(current.normalizedReading()).isEqualTo("2");
        Integer versionRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-eq'", Integer.class);
        assertThat(versionRows).isEqualTo(2);
        // 两次成功源输入都必须留下收件（含未推进版本的一次）
        Integer receiptRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM reading_receipt WHERE observation_id = 'obs-eq'", Integer.class);
        assertThat(receiptRows).isEqualTo(3);
    }

    @Test
    void concurrentSameRequestIdReplaysSingleDimensionalResult() throws Exception {
        observationService.create(new CreateObservationRequest(
                "req-r0", "obs-rep", "站点A", "1", "基线", "LENGTH", "m", null));

        // 同一 requestId、相同带量纲参数并发 4 次：全部返回同一结果，只占一键、只收件一次
        List<Callable<ObservationService.WriteOutcome>> tasks = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            tasks.add(() -> observationService.merge("obs-rep", new MergeObservationRequest(
                    "req-r1", 1, "站点A", "150", "基线", "LENGTH", "cm", null)));
        }
        List<ObservationService.WriteOutcome> outcomes = runConcurrently(tasks);

        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
        assertThat(outcomes).allMatch(outcome -> outcome.body().version() == 2);
        assertThat(outcomes).allMatch(outcome -> "1.50".equals(outcome.body().normalizedReading()));
        ObservationResponse current = observationService.getCurrent("obs-rep");
        assertThat(current.version()).isEqualTo(2);
        assertThat(current.normalizedReading()).isEqualTo("1.50");
        Integer requestRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM request_log WHERE request_id = 'req-r1'", Integer.class);
        assertThat(requestRows).isEqualTo(1);
        Integer receiptRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM reading_receipt WHERE request_id = 'req-r1'", Integer.class);
        assertThat(receiptRows).isEqualTo(1);
        Integer versionRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-rep'", Integer.class);
        assertThat(versionRows).isEqualTo(2);
    }

    @Test
    void concurrentCrossDimensionSubmissionFailsCleanly() throws Exception {
        observationService.create(new CreateObservationRequest(
                "req-x0", "obs-xdim", "站点A", "1", "基线", "LENGTH", "m", null));

        // 并发提交一个合法合并与一个跨量纲合并：跨量纲必须 400，且不留下任何部分结果
        List<Callable<String>> tasks = List.of(
                () -> {
                    try {
                        observationService.merge("obs-xdim", new MergeObservationRequest(
                                "req-x1", 1, "站点A", "2", "基线", "LENGTH", "m", null));
                        return "ok";
                    } catch (ApiException e) {
                        return String.valueOf(e.status().value());
                    }
                },
                () -> {
                    try {
                        observationService.merge("obs-xdim", new MergeObservationRequest(
                                "req-x2", 1, "站点A", "1", "基线", "TEMPERATURE", "C", null));
                        return "ok";
                    } catch (ApiException e) {
                        return String.valueOf(e.status().value());
                    }
                });
        List<String> results = runConcurrently(tasks);

        assertThat(results).containsExactlyInAnyOrder("ok", "400");
        ObservationResponse current = observationService.getCurrent("obs-xdim");
        assertThat(current.version()).isEqualTo(2);
        assertThat(current.normalizedReading()).isEqualTo("2");
        // 跨量纲失败不占键、不留收件
        Integer requestRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM request_log WHERE request_id = 'req-x2'", Integer.class);
        assertThat(requestRows).isZero();
        Integer receiptRows = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM reading_receipt WHERE observation_id = 'obs-xdim'", Integer.class);
        assertThat(receiptRows).isEqualTo(2);
    }
}

package com.example.starter.observation;

import java.math.BigDecimal;
import java.util.regex.Pattern;

/**
 * 一次带量纲读数输入：原值、原始单位与精确规范值。
 *
 * <p>解析规则：dimension 与 readingUnit 必须同时出现或同时缺省（同时缺省表示旧无单位读数，返回 null）；
 * 单位必须受支持且属于所给量纲，值必须是最多三位小数的十进制字符串；任何违反均抛 400。
 * 规范值按单位精确换算（cm/100、K-273.15），不舍入，合并比较使用该精确值。
 *
 * @param dimension       读数量纲
 * @param unit            原始单位
 * @param value           原始读数（十进制原文，最多三位小数）
 * @param normalizedValue 精确规范读数（长度 m、温度 C，十进制原文，可能超过三位小数）
 */
public record DimensionalReading(Dimension dimension, ReadingUnit unit, String value, String normalizedValue) {

    private static final Pattern VALUE_PATTERN = Pattern.compile("-?\\d+(\\.\\d{1,3})?");

    /**
     * 解析请求中的量纲读数；dimension 与 readingUnit 均缺省时返回 null（旧无单位读数，不推断量纲）。
     */
    public static DimensionalReading parse(String dimension, String unit, String value) {
        if (dimension == null && unit == null) {
            return null;
        }
        if (dimension == null || unit == null) {
            throw ApiException.badRequest("dimension and readingUnit must be provided together");
        }
        Dimension parsedDimension = Dimension.fromValue(dimension);
        if (parsedDimension == null) {
            throw ApiException.badRequest("unsupported dimension: " + dimension);
        }
        ReadingUnit parsedUnit = ReadingUnit.fromSymbol(unit);
        if (parsedUnit == null || parsedUnit.dimension() != parsedDimension) {
            throw ApiException.badRequest(
                    "unsupported unit for dimension " + parsedDimension.name() + ": " + unit);
        }
        if (value == null || !VALUE_PATTERN.matcher(value).matches()) {
            throw ApiException.badRequest(
                    "reading must be a decimal string with at most 3 fraction digits");
        }
        return new DimensionalReading(parsedDimension, parsedUnit, value,
                parsedUnit.normalize(new BigDecimal(value)).toPlainString());
    }
}

package com.example.starter.observation;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * 带量纲读数解析与规范化单元测试：单位归属、精确换算（不舍入）与 400 分支。
 */
class DimensionalReadingTest {

    @Test
    void centimetersNormalizeToMetersExactly() {
        DimensionalReading reading = DimensionalReading.parse("LENGTH", "cm", "100");
        assertThat(reading.dimension()).isEqualTo(Dimension.LENGTH);
        assertThat(reading.unit()).isEqualTo(ReadingUnit.CENTIMETER);
        assertThat(reading.value()).isEqualTo("100");
        assertThat(reading.normalizedValue()).isEqualTo("1.00");
    }

    @Test
    void normalizationKeepsMoreThanThreeFractionDigits() {
        // 1.234 cm = 0.01234 m：规范值精确保留，比较不得舍入到三位小数
        DimensionalReading reading = DimensionalReading.parse("LENGTH", "cm", "1.234");
        assertThat(reading.normalizedValue()).isEqualTo("0.01234");
    }

    @Test
    void kelvinNormalizesToCelsiusExactly() {
        DimensionalReading freezing = DimensionalReading.parse("TEMPERATURE", "K", "273.15");
        assertThat(freezing.normalizedValue()).isEqualTo("0");
        DimensionalReading warm = DimensionalReading.parse("TEMPERATURE", "K", "300");
        assertThat(warm.normalizedValue()).isEqualTo("26.85");
    }

    @Test
    void canonicalUnitsKeepOriginalValue() {
        assertThat(DimensionalReading.parse("LENGTH", "m", "1.5").normalizedValue()).isEqualTo("1.5");
        assertThat(DimensionalReading.parse("TEMPERATURE", "C", "-40").normalizedValue()).isEqualTo("-40");
    }

    @Test
    void missingDimensionAndUnitMeansLegacyUnitlessReading() {
        assertThat(DimensionalReading.parse(null, null, "1.0")).isNull();
    }

    @Test
    void dimensionWithoutUnitOrReverseIsRejected() {
        assertThatThrownBy(() -> DimensionalReading.parse("LENGTH", null, "1.0"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
        assertThatThrownBy(() -> DimensionalReading.parse(null, "m", "1.0"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
    }

    @Test
    void unsupportedDimensionOrUnitIsRejected() {
        assertThatThrownBy(() -> DimensionalReading.parse("MASS", "kg", "1.0"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
        assertThatThrownBy(() -> DimensionalReading.parse("LENGTH", "mm", "1.0"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
        assertThatThrownBy(() -> DimensionalReading.parse("TEMPERATURE", "F", "1.0"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
    }

    @Test
    void unitOutsideDimensionIsRejected() {
        // 温度单位不能用于长度量纲，反之亦然
        assertThatThrownBy(() -> DimensionalReading.parse("LENGTH", "C", "1"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
        assertThatThrownBy(() -> DimensionalReading.parse("TEMPERATURE", "cm", "1"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
    }

    @Test
    void valueWithMoreThanThreeFractionDigitsIsRejected() {
        assertThatThrownBy(() -> DimensionalReading.parse("LENGTH", "m", "1.2345"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
        assertThatThrownBy(() -> DimensionalReading.parse("LENGTH", "m", "abc"))
                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).status().value()).isEqualTo(400);
    }

    @Test
    void dimensionNameIsCaseInsensitive() {
        DimensionalReading reading = DimensionalReading.parse("length", "m", "2");
        assertThat(reading.dimension()).isEqualTo(Dimension.LENGTH);
    }
}

